import fs from 'fs';
const b=await chromium.launch({executablePath:process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE,headless:true});
const p=await (await b.newContext({viewport:{width:390,height:844}})).newPage();
await p.goto('http://127.0.0.1:8095/#/pages/inspection/index?kind=mid',{waitUntil:'domcontentloaded'});
const refB=fs.readFileSync('artifacts/ref8443-diff/汛中巡检-ref.png').toString('base64');
const mineB=fs.readFileSync('artifacts/ref8443-diff/汛中巡检-mine.png').toString('base64');
const r=await p.evaluate(async ([a,b])=>{
 function load(u){return new Promise(res=>{const img=new Image();img.onload=()=>res(img);img.src='data:image/png;base64,'+u;});}
 const ia=await load(a), ib=await load(b);
 const w=390,h=844; const c1=document.createElement('canvas');c1.width=w;c1.height=h;const x1=c1.getContext('2d');x1.drawImage(ia,0,0);
 const c2=document.createElement('canvas');c2.width=w;c2.height=h;const x2=c2.getContext('2d');x2.drawImage(ib,0,0);
 const d1=x1.getImageData(0,0,w,h).data, d2=x2.getImageData(0,0,w,h).data;
 const rows=[]; for(let y=0;y<h;y+=40){let c=0; for(let yy=y;yy<Math.min(y+40,h);yy++)for(let x=0;x<w;x++){const i=(yy*w+x)*4; if(Math.abs(d1[i]-d2[i])+Math.abs(d1[i+1]-d2[i+1])+Math.abs(d1[i+2]-d2[i+2])>30)c++;} rows.push(y+':'+c);} return rows;},[refB,mineB]);
console.log(r.join('  '));
await b.close();
"

